import { Component, OnInit } from '@angular/core';
import {$$, api, now, showError, showMessage} from "../tools";
import {MatSnackBar} from "@angular/material/snack-bar";
import {ConfigService} from "../config.service";
import {ApiService} from "../api.service";
import {Location} from "@angular/common";
import {ActivatedRoute, Router} from "@angular/router";
import {ImageSelectorComponent} from "../image-selector/image-selector.component";
import {MatDialog} from "@angular/material/dialog";

const reg_url = '(https?://)?([\\da-z.-]+)\\.([a-z.]{2,6})[/\\w .-]*/?';

@Component({
  selector: 'app-addpow',
  templateUrl: './addpow.component.html',
  styleUrls: ['./addpow.component.sass']
})
export class AddpowComponent implements OnInit {

  pows: any[]=[]
  profils: any[]=[]
  showDetail=false
  pow: any
  link:any={url:"",text:""};
  message: string="";
    handle_query: NodeJS.Timeout;

  constructor(public _location:Location,
              public dialog:MatDialog,
              public routes:ActivatedRoute,
              public router:Router,
              public api:ApiService,
              public config:ConfigService,
              public toast:MatSnackBar) { }

  ngOnInit(): void {
    this.initPow();
  }

  initPow(){
    this.pow={title:"",links:[],description:"",visual:"",year:now("year")};
    this.pow.owner=this.routes.snapshot.queryParamMap.get("owner");
    this.refresh_femis_db("femis_OASIS_films.xlsx","Résultats")
    this.refresh_femis_db("femis_OASIS_casting.xlsx","Résultats")
    this.refresh_femis_db("femis_db.xlsx","Résultats")
  }


  quit(bSave=true) {
    if(bSave){
      let id_work=this.routes.snapshot.queryParamMap.get("id");
      if(this.pow.hasOwnProperty('id')){
        if(this.routes.snapshot.queryParamMap.get("redirect")=="addwork") {
          $$("Le titre est déjà dans la base on retourne à l'ajout d'expérience");
          this.router.navigate(["edit"], {
            queryParams:
              {
                id: id_work,
                add: this.pow.id,
                title: this.pow.title
              }
          });
        }
      } else {
        $$("Le titre n'est pas dans la base, on l'enregistre")
        //this.pow.links=JSON.stringify(this.pow.links);
        this.api.addpow(this.pow).subscribe((r:any)=>{
          showMessage(this,"Enregistré");
          if(this.routes.snapshot.queryParamMap.get("redirect")=="addwork"){
            this.router.navigate(["edit"],{queryParams:
                {
                  id:id_work,
                  add:r.id,
                  title:r.title
                },
              replaceUrl:true
            });
          } else {
            this.initPow();
            this.showDetail=false;
          }
        });
      }
    } else {
      this._location.back();
    }

  }

  changeTitle(evt: any) {
      //http://localhost:8000/api/powsdoc/?format=json&limit=200&search_simple_query_string=%22les%20chiens%22
    if(evt.length>2){
        clearTimeout(this.handle_query);
        this.handle_query=setTimeout(()=>{
            this.api._get("powsdoc","search_simple_query_string="+evt).subscribe((r:any)=>{
                this.pows=r.results;
            })
        },300);

    } else {
      this.pows=[];
    }
  }

  add_title() {
    this.showDetail=true;
  }

  select_title(pow:any) {
    this.pow=pow;
    this.quit(true);
  }

  remove(_url: any) {
    this.pow.links.splice(this.pow.links.indexOf(_url),1);
  }

  add_link() {
    if(!this.link.url.startsWith("http"))this.link.url="https://"+this.link.url;
    this.pow.links.push(this.link);
    this.link={url:"",text:""};
  }


  change_visual() {
  this.dialog.open(ImageSelectorComponent, {position:
        {left: '5vw', top: '5vh'},
      maxWidth: 400, maxHeight: 700, width: '50vw', height: '90vh', data:
                {
                  result: this.pow.visual,
                  checkCode: true,
                  width: 200,
                  height: 200,
                  emoji: false,
                  internet: false,
                  ratio: 1,
                  quality:0.7
                }
            }).afterClosed().subscribe((result) => {
      if (result) {
        this.pow.visual= result;
      }
    });
  }


   _import(fileInputEvent: any) {
      var reader = new FileReader();
      let filename=fileInputEvent.target.files[0].name;
      let format=filename.split(".")[1];
      this.message="Chargement du fichier";
      reader.onload = ()=>{
        let body={
              filename:fileInputEvent.target.files[0].name,
              size:fileInputEvent.target.files[0].size,
              type:fileInputEvent.target.files[0].type,
              file:reader.result,
              dictionnary:{}
            }
        this.message="Importation du fichier de films";
        this.api._post("movie_importer/","",body,200).subscribe((r:any)=>{
          this.message="";
          showMessage(this,r);
          this.router.navigate(["pows"])
        },(err)=>{
          showError(this,err);
        })
      };
      reader.readAsDataURL(fileInputEvent.target.files[0]);
  }

  refresh_femis_db(db_file="",sheet_name="data"){
    this.api._get("femis_db_files","filename="+db_file+"&type=pow&sheet_name="+sheet_name).subscribe({
      next:(rc:any)=>{
        this.pows=rc.results["pows"]
        this.profils=rc.results["profils"]
      },
      error:(err:any)=>{
        showError(this,err)
      }
    })
  }


  upload_femis_db_file($event: any,filename="",sheet_name="data") {
    this.api._post("femis_db_files","filename="+filename+"&sheet_name="+sheet_name,$event).subscribe({
      next:()=>{
        showMessage(this,"Fichier chargé")
        this.refresh_femis_db(filename,sheet_name)
      }
    })
  }

  get_femisbase() {
    open(api("femis_db_files","type=file"),"blank");
  }

  select_row($event: any) {
    this.router.navigate(["pows"],{queryParams:{query:$event.value}})
  }

  select_row_casting($event: any) {
    this.router.navigate(["search"],{queryParams:{query:$event.value}})
  }
}
