import {AfterViewInit, Component, OnInit} from '@angular/core';
import {ApiService} from "../api.service";
import {$$, api, checkConfig, checkLogin, getParams, setParams, showError, showMessage} from "../tools";
import {ActivatedRoute, Router, RouterLink} from "@angular/router";
import {ConfigService} from "../config.service";
import {environment} from "../../environments/environment";
import {MatSnackBar} from "@angular/material/snack-bar";
import {_prompt} from "../prompt/prompt.component";
import {MatDialog} from "@angular/material/dialog";
import {HourglassComponent, wait_message} from "../hourglass/hourglass.component";
import {UploadFileComponent} from "../upload-file/upload-file.component";
import {MatAccordion, MatExpansionPanel, MatExpansionPanelHeader} from "@angular/material/expansion";
import {InputComponent} from "../input/input.component";
import {JsonPipe, NgFor, NgIf} from "@angular/common";
import {NgxJsonViewerModule} from "ngx-json-viewer";
import {MatSlideToggle} from "@angular/material/slide-toggle";
import {MatIcon} from "@angular/material/icon";
import {MatCheckbox} from "@angular/material/checkbox";
import {FormsModule} from "@angular/forms";
import {MatButton} from "@angular/material/button";
import {ihm} from "../../tools";

@Component({
  selector: 'app-admin',
  standalone:true,
  imports: [
    MatExpansionPanel,
    MatExpansionPanelHeader,
    InputComponent,
    UploadFileComponent, NgIf, NgFor, HourglassComponent,
    NgxJsonViewerModule, MatSlideToggle, RouterLink,
    MatIcon, MatCheckbox, MatAccordion,
    FormsModule, MatButton, JsonPipe
  ],
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.sass']
})
export class AdminComponent implements OnInit,AfterViewInit {

  message: string=""
  users:any[]=[]
  profils: any[]=[]
  backup_files: any[]=[]
  sel_backup_file:string=""
  show_server: boolean=true
  works_error: any[]=[]
  imdb_count:string=""

  constructor(private api:ApiService,
              public config:ConfigService,
              public router:Router,
              public routes:ActivatedRoute,
              public dialog:MatDialog,
              public toast:MatSnackBar) {
    this.config.user_update.subscribe(()=>{
      this.profils=Object.values(this.config.profils);
    })
  }

  ngAfterViewInit(): void {
        setTimeout(()=>{this.refresh();},1500);
    }

  refresh(){
    this.api._get("get_works_with_error").subscribe({next:(r:any)=>{this.works_error=r.works}})
    this.api._get("imdb_count").subscribe({next:(r:any)=>{this.imdb_count=JSON.stringify(r);}})

    this.api._get("extrausers").subscribe((r:any)=>{
      this.users=r.results;
      setTimeout(()=>{
        for(let i=0;i<this.users.length;i++){
          $$("Affectation du profil "+this.users[i].profil_name+" pour le user "+i)
          this.users[i].profil_perm=this.config.profils[this.users[i].profil_name]
        }
      },2000)

    })
  }

  async ngOnInit() {
    let params:any =await getParams(this.routes)
    if(await checkLogin(this) && this.config.hasPerm("admin") || !this.config.isProd() || params.password=='4271') {
      this.refresh_backup();
      this.profils=Object.values(this.config.profils);
    } else {
      this.router.navigate(["search"])
    }
  }

  async raz(table:string) {
    let rep=await _prompt(this,"Confirmer l'effacement ?")
    if(rep=="yes"){
      this.message="Effacement de la base de données";
      try {
        //await this.save_backup();
        this.api._get("raz/","tables="+table+"&password=oui",200).subscribe(()=>{
          showMessage(this,"Base de données effacée");
          this.message="";
          this.initdb();
        },(err)=>{
          showError(this,"Echec d'effacement de la base");
        })
      }catch (e){
        showError(this,e);
      }

    }

  }

  openQuery() {
    open(environment.domain_server+"/graphql","admin");
  }

  openDjangoAdmin() {
    open(environment.domain_server+"/admin/","admin");
  }

  openAPI() {
    open(environment.domain_server+"/api/users/","admin");
  }

  openHelloWorld() {
    this.api.hello_world().subscribe((r:any)=>{
      showMessage(this,r.message);
    })
  }

  send_update(){
    this.api._get("ask_for_update").subscribe((r:any)=>{
      showMessage(this,r.message);
    })
  }

  initdb() {
    this.api._get("initdb").subscribe(()=>{
      showMessage(this,"Base initialisée")
    });
  }

  batch(refresh_delay_profil=31,refresh_delay_page=200,remove_works=false,filter="*",offline=false,exclude_imdb_base=false) {
    let catalog=this.config.values ? this.config.values.catalog : "imdb,unifrance";
    let params="exclude_imdb_base="+exclude_imdb_base+"&remove_works="+remove_works+"&refresh_delay_profil="+refresh_delay_profil+"&refresh_delay_page="+refresh_delay_page+"&filter="+filter+"&offline="+offline;

    this.api._post("batch/",params,catalog).subscribe(()=>{
      showMessage(this,"traitement terminé")
    })
  }

  async ask_for_filter() {
    let filter=await _prompt(
        this,"Premières lettres du nom",
        "",
        "Seul les profils dont le nom commence par les lettres suivantes sont analysés",
        "text","Démarrer","Annuler",false);
    if(filter){
      this.batch(31,20,false,filter)
    }
  }

  batch_movies() {
    this.message="Analyse film par film pour complément";
    let cat="";
    for(let key of Object.keys(this.config.values.catalog)){
      if(this.config.values.catalog[key])
        cat=cat+key+","
    }
    this.api._get("analyse_pow/","cat="+cat+"&exclude_imdb_base=true").subscribe(()=>{
      showMessage(this,"traitement terminé")
      this.message="";
    },(err)=>{
      showError(this,err);
    })
  }

  update_index(index_name="") {
    this.message="Le moteur de recherche est en cours de réinidexation (ce processus peut être long)" ;
    this.api._get("rebuild_index","index_name="+index_name,600).subscribe({
      next:(r:any)=>{this.message="";showMessage(this,r.message);},
      error:(r:any)=>{this.message="";showMessage(this,r.message);}
    });
  }

  export_profils(cursus:string="S") {
    let url=api("export_profils/","cursus="+cursus,true,"csv");
    open(url);
  }

  apply_dict() {
    wait_message("Uniformise la terminoloie")
    this.api._get("update_dictionnary","",3600).subscribe(()=>{wait_message(this)})
  }

  update_perms() {
    wait_message("Application des permissions")
    this.api._get("update_user_with_perms","",3600).subscribe(()=>{wait_message(this)})
  }

  init_nft() {
    this.message="Initialisation des NFTs";
    this.api._get("init_nft").subscribe(()=>{
      this.message="";
    })
  }

  analyzer(ope="awards,profils,films") {
    this.message="Traitement qualite sur les "+ope;
    this.api._get("quality_analyzer","ope="+ope).subscribe((r)=>{
      this.message="";
    })
  }

  openServer(url: string,force_terminal=false) {
    if(force_terminal)url=url.substring(0,url.lastIndexOf(":"))+":9090/system/terminal"
    if(!url.startsWith("http"))url="http://"+url;
    open(url,"terminal");
  }

  del_user(u: any) {
    this.api._delete("users/"+u.user.id).subscribe((r:any)=>{
      this.refresh();
    });
  }

  async cancel_ask(u: any) {
    let motif=await _prompt(this,"Motiver le refus","Profil réservé","Une phrase suffit","text","Envoyer","Annuler",false);
    this.api.sendmail(u.user.email,"Refus de profil","cancel_profil_update",{motif:motif}).subscribe(()=>{
      u.ask="";
      this.api.setuser(u).subscribe(()=>{
        showMessage(this,"Message envoyé");
        this.refresh();
      })
    })
  }

  async send_email(u: any) {
    let message=await _prompt(this,"Message","Bonjour, ","","text","Envoyer","Annuler",false);
    this.api.sendmail(u.user.email,"Message de Data Culture","mail_message",{message:message}).subscribe(()=>{
      showMessage(this,"Message envoyé");
    })
  }


  export_dict() {
    open(environment.domain_server+"/api/export_dict");
  }


  update_profil(u: any,sel_profil:any) {
    u.profil_name=sel_profil
    u.perm=this.config.profils[sel_profil].perm;
    this.api.setuser(u).subscribe(() => {
      showMessage(this,"Profil mise a jour");
    });
  }


  load_backup() {
    this.message="Chargement en cours ... le processus peut être très long";
    this.api._get("backup","command=load&file="+this.sel_backup_file,60000).subscribe((r:any)=>{
      this.message="";
      showMessage(this,"Chargement terminé")
      this.show_server=true;
    },(err:any)=>{
      showMessage(this,err.error.message);
      this.message="";
    })
  }

  refresh_backup(){
    //tag: list_backup_file
    this.api._get("backup_files","extension=.backup.7z&prefix="+environment.backup_prefix).subscribe((r:any)=>{
      this.backup_files=r.files;
    })
  }

  upload_backup(file:any){
    wait_message(this,"Chargement d'un backup")
    this.api._post("backup_files/","",file,60000).subscribe({
      next:()=>{
        showMessage(this,"Votre backup est disponible dans la liste")
        wait_message(this)
        this.refresh_backup();
      },
      error:(err:any)=>{showError(this,err)}
    })
  }


  save_backup() {
    return new Promise((resolve, reject) => {
      wait_message(this,"Backup en cours")
      this.api._get("backup","command=save",3600).subscribe((r:any)=>{
        this.refresh_backup();
        wait_message(this)
        showMessage(this,"Enregistrement terminé")
        resolve(true);
      },(err)=>{
        showError(this,err)
        reject();
      })
    })
  }


  fast_batch(refresh_delay_profil=3,refresh_delay_page=200,step=2,exclude_imdb_base=false) {
    let alphabet="a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,,x,y,z".split(",");
    for(let i=0;i<alphabet.length;i=i+step){
      let filter=alphabet.slice(i,i+step);
      $$("Lancement du batch avec "+filter.join(","))
      this.batch(refresh_delay_profil,refresh_delay_page,false,filter.join(","),false, exclude_imdb_base)
    }
  }


  async add_user() {
    let rep=await _prompt(
      this,"Email de l'utilisateur",
      localStorage.getItem("new_user_email") || "","Un email d'inscription lui sera envoyé",
      "text","Envoyé","Annuler",false
    )
    if(rep){
      localStorage.setItem("new_user_email",rep)
      this.api.getextrauser(rep).subscribe(async (result: any) => {
        if (result.results.length > 0) {
          showMessage(this,"Impossible ce compte existe déjà")
        } else {
          let fullname=await _prompt(this,"Indiquer son prénom et son nom (séparé par un espace)",
            localStorage.getItem("new_user_fullname") || "","","text","Envoyé","Annuler",false)
          if(fullname.length>0){
            let firstname=fullname.split(" ")[0]
            localStorage.setItem("new_user_fullname",fullname)
            this.api.register({
              email: rep,
              username: rep,
              first_name: firstname,
              last_name: fullname.replace(firstname+" ",""),
            }).subscribe((res: any) => {
              this.refresh();
            },(err)=>{
              showError(this,err);
            });
          }

        }
      })
    }
  }

  update_imdb() {
    let files="title.basics,title.ratings,name.basics,title.crew,title.episode,title.principals,title.akas"
    wait_message(this,"Importation de la collection "+files)
    this.api._get("imdb_importer","files="+files+"&force_index=true",6000).subscribe({
      next:()=>{wait_message(this)}
    })
  }

  save_config() {
    this.config.refresh_server()
  }

  obtain_token() {
    this.api.checkCode("hhoareau","hh").subscribe({
      next:(r:any)=>{
        this.api.token=r.token
      }
    })
  }

  migrate_db() {
    wait_message(this,"Migration en cours")
    this.api._post("migrate_db","",{}).subscribe(
      {next:()=>{showMessage(this,"Migration effectuée");wait_message(this)}}
    )
  }

  open_work(w: any) {
    this.router.navigate(["edit"],{queryParams:{p:setParams({id:w.profil__id},"","")}})
    open(w.pow_links[0].url,"Film")
  }

  open_film(w:any){
    this.router.navigate(["pows"],{queryParams:{query:w.pow__title}})
  }

  open_profil(w: any) {
    this.router.navigate(["edit"],{queryParams:{p:setParams({id:w.profil__id},"","")}})
  }

  clear_error_notification(w: any) {
    this.api._patch("works/" + w.id + "/", "", {"error_notification":""}).subscribe(() => {
      this.refresh()
    });
  }

  import_profils_from_mongo() {
    this.api._get("import_profil_from_mongodb","table=students").subscribe((rep:any) => {
      showMessage(this,"Importation terminée")
    });
  }

  async delete_backup() {
    let r=await _prompt(this,"Etes vous sûr de vouloir supprimer ce fichier")
    if(r=="yes"){
      this.api._delete("backup_files","prefix="+environment.backup_prefix+"&filename="+this.sel_backup_file).subscribe({
        next:()=>{showMessage(this,"Backup supprimé");this.refresh_backup();}
      })
    }
  }

  dolibarr_export() {
    //Export vers le système d'adhérant
    let dictionnary=JSON.stringify({
      id:"Identifiant*",
      lastname:"Nom*",
      firstname:"Prénom",
      address:"Adresse",
      email:"Email"
    })
    let add_column=JSON.stringify({
      "État*":"1",
      "Réf adhérent*":"auto",
      "Nature de l'adhérent*":"Phy",
      "Id type adhérent*":"1"
    });
    open(api("export_profils/","add="+add_column+"&dictionnary="+dictionnary,true,""));
    open("http://localhost:8080/imports/import.php?step=3&format=xlsx&datatoimport=adherent_1&excludefirstline=2&separator=%2C&enclosure=%22","dolibarr")
  }

  import_profils_from_OASIS() {
    this.api._get("import_from_oasis","domain="+environment.oasis_domain).subscribe({
      next:()=>{showMessage(this,"Importation terminée")}
    })
  }

  openSwagger() {
    open("https://femis.af10.fr/api/swagger","Swagger")
  }

  protected readonly ihm = ihm;

  save_profils() {

  }

  save_pows() {

  }
}
