import { Component, OnInit } from '@angular/core';
import {ApiService} from "../api.service";
import {ConfigService} from "../config.service";
import {showMessage} from "../tools";
import {MatSnackBar} from "@angular/material/snack-bar";
import {Location} from "@angular/common"
import {InputComponent} from "../input/input.component";


@Component({
  selector: 'app-issues',
  templateUrl: './issues.component.html',
  styleUrls: ['./issues.component.sass']
})
export class IssuesComponent implements OnInit {
  title="";
  description="";
  localisation="";
  screen_capture: any;

  constructor(
    public api:ApiService,
    public _location:Location,
    public toast:MatSnackBar,
    public config:ConfigService,
  ) { }

  ngOnInit(): void {

  }

  send() {
    let body="De 'user"+this.config.user.user.id+"'\nLocalisation: "+this.localisation+"\nDescription:"+this.description;
    this.api._post("add_issue","",{author:this.config.user.user.email, description:this.description,localisation:this.localisation,title:this.title,body:body,screen:this.screen_capture}).subscribe((r)=>{
      showMessage(this,"Merci pour votre contribution");
    });
    this.quit();
  }

  quit() {
    this._location.back();
  }

  upload_screen($event: any) {
    this.screen_capture=$event;
  }
}
